/// Returns `x` limited to the closed range `[lo, hi]`.
/// Requires `lo <= hi`.
pub fn clamp(x: i64, lo: i64, hi: i64) -> i64 {
    if x < lo {
        lo
    } else if x > hi {
        hi
    } else {
        x
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    #[test]
    fn basics() {
        assert_eq!(clamp(5, 0, 10), 5);
        assert_eq!(clamp(-5, 0, 10), 0);
        assert_eq!(clamp(15, 0, 10), 10);
        assert_eq!(clamp(0, 0, 0), 0);
        assert_eq!(clamp(i64::MIN, i64::MIN, i64::MAX), i64::MIN);
        assert_eq!(clamp(i64::MAX, i64::MIN, i64::MAX), i64::MAX);
        assert_eq!(clamp(i64::MIN, 3, 3), 3);
        assert_eq!(clamp(i64::MAX, -3, -3), -3);
    }

    proptest! {
        #[test]
        fn prop(x in any::<i64>(), a in any::<i64>(), b in any::<i64>()) {
            let (lo, hi) = if a <= b { (a, b) } else { (b, a) };
            let r = clamp(x, lo, hi);
            prop_assert!(lo <= r && r <= hi);
            prop_assert_eq!(r, x.clamp(lo, hi));
            if lo <= x && x <= hi { prop_assert_eq!(r, x); }
        }
    }
}

/// Returns floor((a + b) / 2) computed exactly, without overflow.
pub fn midpoint(a: i64, b: i64) -> i64 {
    // Common bits plus half of the differing bits (arithmetic shift floors).
    (a & b) + ((a ^ b) >> 1)
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    fn reference(a: i64, b: i64) -> i64 {
        ((a as i128 + b as i128).div_euclid(2)) as i64
    }

    #[test]
    fn edge_cases() {
        let vals = [i64::MIN, i64::MIN + 1, -3, -2, -1, 0, 1, 2, 3, i64::MAX - 1, i64::MAX];
        for &a in &vals {
            for &b in &vals {
                assert_eq!(midpoint(a, b), reference(a, b), "a={a} b={b}");
            }
        }
        assert_eq!(midpoint(-1, 0), -1);
        assert_eq!(midpoint(1, 0), 0);
        assert_eq!(midpoint(i64::MIN, i64::MAX), -1);
    }

    proptest! {
        #[test]
        fn matches_reference(a in any::<i64>(), b in any::<i64>()) {
            prop_assert_eq!(midpoint(a, b), reference(a, b));
        }
        #[test]
        fn small(a in -100i64..100, b in -100i64..100) {
            prop_assert_eq!(midpoint(a, b), reference(a, b));
        }
    }
}

pub fn sat_sum(a: &[i64]) -> i64 {
    a.iter().fold(0i64, |acc, &x| acc.saturating_add(x))
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    fn model(a: &[i64]) -> i64 {
        let mut t: i128 = 0;
        for &x in a {
            t = (t + x as i128).clamp(i64::MIN as i128, i64::MAX as i128);
        }
        t as i64
    }

    #[test]
    fn basics() {
        assert_eq!(sat_sum(&[]), 0);
        assert_eq!(sat_sum(&[1, 2, 3]), 6);
        assert_eq!(sat_sum(&[i64::MAX, 1, -1]), i64::MAX - 1);
        assert_eq!(sat_sum(&[i64::MIN, -1, 1]), i64::MIN + 1);
        assert_eq!(sat_sum(&[i64::MAX, i64::MIN]), -1);
    }

    proptest! {
        #[test]
        fn matches_model(a in proptest::collection::vec(any::<i64>(), 0..20)) {
            prop_assert_eq!(sat_sum(&a), model(&a));
        }
        #[test]
        fn matches_model_edges(a in proptest::collection::vec(prop_oneof![Just(i64::MAX), Just(i64::MIN), -3i64..3], 0..20)) {
            prop_assert_eq!(sat_sum(&a), model(&a));
        }
    }
}

/// Count elements x of `a` with lo <= x <= hi (inclusive). Returns 0 if lo > hi.
pub fn count_in_range(a: &[i64], lo: i64, hi: i64) -> usize {
    if lo > hi {
        return 0;
    }
    a.iter().filter(|&&x| lo <= x && x <= hi).count()
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    #[test]
    fn basics() {
        assert_eq!(count_in_range(&[], 0, 10), 0);
        assert_eq!(count_in_range(&[1, 2, 3, 4, 5], 2, 4), 3);
        assert_eq!(count_in_range(&[1, 2, 3], 3, 1), 0);
        assert_eq!(count_in_range(&[5, 5, 5], 5, 5), 3);
        assert_eq!(count_in_range(&[i64::MIN, i64::MAX, 0], i64::MIN, i64::MAX), 3);
        assert_eq!(count_in_range(&[i64::MIN, i64::MAX], i64::MAX, i64::MAX), 1);
        assert_eq!(count_in_range(&[i64::MIN, i64::MAX], i64::MIN, i64::MIN), 1);
        assert_eq!(count_in_range(&[0], i64::MAX, i64::MIN), 0);
    }

    proptest! {
        #[test]
        fn matches_reference(a in proptest::collection::vec(any::<i64>(), 0..50),
                             lo in any::<i64>(), hi in any::<i64>()) {
            let expected = a.iter().filter(|&&x| (lo as i128) <= x as i128 && (x as i128) <= hi as i128).count();
            prop_assert_eq!(count_in_range(&a, lo, hi), expected);
        }

        #[test]
        fn small_values(a in proptest::collection::vec(-5i64..5, 0..50),
                        lo in -6i64..6, hi in -6i64..6) {
            let mut expected = 0;
            for &x in &a { if lo <= x && x <= hi { expected += 1; } }
            if lo > hi { prop_assert_eq!(expected, 0); }
            prop_assert_eq!(count_in_range(&a, lo, hi), expected);
        }
    }
}

/// Returns the smallest index `i` such that `a[i]` is a maximum of `a`.
/// Panics-free for non-empty input; returns 0 for an empty slice.
pub fn first_max_index(a: &[i64]) -> usize {
    let mut best = 0usize;
    for i in 1..a.len() {
        if a[i] > a[best] {
            best = i;
        }
    }
    best
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    #[test]
    fn basics() {
        assert_eq!(first_max_index(&[5]), 0);
        assert_eq!(first_max_index(&[1, 3, 3, 2]), 1);
        assert_eq!(first_max_index(&[i64::MIN, i64::MIN]), 0);
        assert_eq!(first_max_index(&[-1, i64::MAX, 0, i64::MAX]), 1);
        assert_eq!(first_max_index(&[1, 2, 3]), 2);
    }

    proptest! {
        #[test]
        fn prop(a in prop::collection::vec(prop_oneof![any::<i64>(), -3i64..3], 1..50)) {
            let i = first_max_index(&a);
            let m = *a.iter().max().unwrap();
            prop_assert_eq!(a[i], m);
            prop_assert!(a[..i].iter().all(|&x| x < m));
        }
    }
}

/// Returns the largest index `i` such that `a[i]` is a minimum of `a`.
pub fn last_min_index(a: &[i64]) -> usize {
    let mut best = 0;
    for (i, &x) in a.iter().enumerate() {
        if x <= a[best] {
            best = i;
        }
    }
    best
}

#[cfg(test)]
mod tests {
