    use proptest::prelude::*;

    #[test]
    fn examples() {
        assert_eq!(last_min_index(&[5]), 0);
        assert_eq!(last_min_index(&[3, 1, 2, 1, 4]), 3);
        assert_eq!(last_min_index(&[1, 2, 3]), 0);
        assert_eq!(last_min_index(&[3, 2, 1]), 2);
        assert_eq!(last_min_index(&[i64::MIN, i64::MAX, i64::MIN]), 2);
        assert_eq!(last_min_index(&[7, 7, 7]), 2);
    }

    proptest! {
        #[test]
        fn prop(a in proptest::collection::vec(-5i64..5, 1..30)) {
            let i = last_min_index(&a);
            let m = *a.iter().min().unwrap();
            prop_assert_eq!(a[i], m);
            prop_assert!(a[i + 1..].iter().all(|&x| x > m));
        }

