        fn prop_full(a in proptest::collection::vec(any::<i64>(), 1..30)) {
            let i = last_min_index(&a);
            let m = *a.iter().min().unwrap();
            prop_assert_eq!(a[i], m);
            prop_assert!(a[i + 1..].iter().all(|&x| x > m));
        }
    }
}

pub fn strictly_increasing(a: &[i64]) -> bool {
    a.windows(2).all(|w| w[0] < w[1])
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    #[test]
    fn basics() {
        assert!(strictly_increasing(&[]));
        assert!(strictly_increasing(&[5]));
        assert!(strictly_increasing(&[i64::MIN, 0, i64::MAX]));
        assert!(!strictly_increasing(&[1, 1]));
        assert!(!strictly_increasing(&[2, 1]));
        assert!(!strictly_increasing(&[1, 2, 3, 3]));
    }

    proptest! {
        #[test]
        fn matches_naive(a in proptest::collection::vec(any::<i64>(), 0..10)) {
            let mut ok = true;
            for i in 0..a.len().saturating_sub(1) {
                if a[i] >= a[i + 1] { ok = false; }
            }
            prop_assert_eq!(strictly_increasing(&a), ok);
        }

        #[test]
        fn sorted_dedup_true(mut a in proptest::collection::vec(any::<i64>(), 0..20)) {
            a.sort();
            a.dedup();
            prop_assert!(strictly_increasing(&a));
        }
    }
}

/// Returns the smallest index `i` with `a[i] >= t`, or `a.len()` if none.
/// `a` must be sorted in non-decreasing order.
pub fn lower_bound(a: &[i64], t: i64) -> usize {
    let mut lo = 0usize;
    let mut hi = a.len();
    // Invariant: all a[..lo] < t, all a[hi..] >= t.
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        if a[mid] < t {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    lo
}

