/// Floor division: a / b rounded toward negative infinity.
pub fn div_floor(a: i64, b: i64) -> i64 {
    let q = a / b;
    let r = a % b;
    // Truncation rounded toward zero; if there is a remainder whose sign
    // differs from the divisor's, the exact quotient was negative and
    // we must step down by one. (q - 1 cannot overflow: q == i64::MIN
    // only for a == i64::MIN, b == 1, where r == 0.)
    if r != 0 && ((r < 0) != (b < 0)) {
        q - 1
    } else {
        q
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    /// Independent reference using i128 and Euclidean division.
    fn reference(a: i64, b: i64) -> i64 {
        let (a, b) = (a as i128, b as i128);
        let f = if b > 0 { a.div_euclid(b) } else { (-a).div_euclid(-b) };
        f as i64
    }

    /// Defining property of floor: q <= a/b < q + 1.
    fn is_floor(a: i64, b: i64, q: i64) -> bool {
        let (a, b, q) = (a as i128, b as i128, q as i128);
        if b > 0 {
            q * b <= a && a < (q + 1) * b
        } else {
            q * b >= a && a > (q + 1) * b
        }
    }

    #[test]
    fn examples() {
        assert_eq!(div_floor(7, 2), 3);
        assert_eq!(div_floor(-7, 2), -4);
        assert_eq!(div_floor(7, -2), -4);
        assert_eq!(div_floor(-7, -2), 3);
        assert_eq!(div_floor(6, 3), 2);
        assert_eq!(div_floor(-6, 3), -2);
        assert_eq!(div_floor(0, -5), 0);
        assert_eq!(div_floor(-20, -1), 20);
        assert_eq!(div_floor(i64::MIN, 1), i64::MIN);
        assert_eq!(div_floor(i64::MIN, 2), i64::MIN / 2);
        assert_eq!(div_floor(i64::MIN, -2), 1i64 << 62);
        assert_eq!(div_floor(i64::MIN, i64::MAX), -2);
        assert_eq!(div_floor(i64::MAX, i64::MIN), -1);
        assert_eq!(div_floor(i64::MIN, i64::MIN), 1);
        assert_eq!(div_floor(i64::MAX, -1), -i64::MAX);
        assert_eq!(div_floor(-1, i64::MAX), -1);
        assert_eq!(div_floor(1, i64::MIN), -1);
    }

    #[test]
    fn edge_grid() {
        let vals = [i64::MIN, i64::MIN + 1, -3, -2, -1, 0, 1, 2, 3, i64::MAX - 1, i64::MAX];
        for &a in &vals {
            for &b in &vals {
                if b == 0 || (a == i64::MIN && b == -1) {
                    continue;
                }
                let q = div_floor(a, b);
                assert_eq!(q, reference(a, b), "a={a} b={b}");
                assert!(is_floor(a, b, q), "a={a} b={b}");
            }
        }
    }

    proptest! {
        #[test]
        fn matches_reference(a in any::<i64>(), b in any::<i64>()) {
            prop_assume!(b != 0 && !(a == i64::MIN && b == -1));
            let q = div_floor(a, b);
            prop_assert_eq!(q, reference(a, b));
            prop_assert!(is_floor(a, b, q));
        }

        #[test]
        fn matches_reference_small(a in -1000i64..1000, b in -20i64..20) {
            prop_assume!(b != 0);
            let q = div_floor(a, b);
            prop_assert_eq!(q, reference(a, b));
            prop_assert!(is_floor(a, b, q));
        }
    }
}

/// Remainder of floor division: a - b * floor(a / b).
pub fn mod_floor(a: i64, b: i64) -> i64 {
    // wrapping_rem avoids the panic for i64::MIN % -1 (result is 0).
    let r = a.wrapping_rem(b);
    if r != 0 && ((r < 0) != (b < 0)) {
        // r and b have opposite signs, so this cannot overflow.
        r + b
    } else {
        r
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    #[test]
    fn examples() {
        assert_eq!(mod_floor(7, 3), 1);
        assert_eq!(mod_floor(-7, 3), 2);
        assert_eq!(mod_floor(7, -3), -2);
        assert_eq!(mod_floor(-7, -3), -1);
        assert_eq!(mod_floor(i64::MIN, -1), 0);
        assert_eq!(mod_floor(i64::MIN, 1), 0);
        assert_eq!(mod_floor(i64::MIN, i64::MAX), i64::MAX - 1);
        assert_eq!(mod_floor(i64::MAX, i64::MIN), -1);
        assert_eq!(mod_floor(i64::MIN, i64::MIN), 0);
        assert_eq!(mod_floor(-1, i64::MIN), -1);
        assert_eq!(mod_floor(1, i64::MIN), i64::MIN + 1);
        assert_eq!(mod_floor(0, 5), 0);
        assert_eq!(mod_floor(1, -2), -1);
    }

    /// Independent reference in i128: floor quotient via Euclidean division.
    fn reference(a: i64, b: i64) -> i64 {
        let (a, b) = (a as i128, b as i128);
        let mut q = a.div_euclid(b);
        // For b < 0 the Euclidean quotient is ceil(a/b); floor is one less
        // unless the division is exact.
        if b < 0 && a.rem_euclid(b) != 0 {
            q -= 1;
        }
        (a - b * q) as i64
    }

    proptest! {
        #[test]
        fn matches_reference(a in any::<i64>(), b in any::<i64>().prop_filter("nz", |b| *b != 0)) {
            let r = mod_floor(a, b);
            prop_assert_eq!(r, reference(a, b));
            prop_assert!(r == 0 || ((r < 0) == (b < 0)));
            prop_assert!((r as i128).abs() < (b as i128).abs());
            // a - r must be divisible by b
            prop_assert_eq!(((a as i128) - (r as i128)) % (b as i128), 0);
        }

        #[test]
        fn extremes(a in prop_oneof![Just(i64::MIN), Just(i64::MAX), Just(i64::MIN + 1), -3i64..3],
                    b in prop_oneof![Just(i64::MIN), Just(i64::MAX), Just(-1i64), Just(1i64), -3i64..3]) {
            prop_assume!(b != 0);
            prop_assert_eq!(mod_floor(a, b), reference(a, b));
        }

        #[test]
        fn small(a in -50i64..50, b in -10i64..10) {
            prop_assume!(b != 0);
            let fl = ((a as f64) / (b as f64)).floor() as i64;
            prop_assert_eq!(mod_floor(a, b), a - b * fl);
        }
    }
}

/// Largest sum of a non-empty contiguous subarray (Kadane's algorithm).
/// Sums are bounded by 1e6 * 1e9 = 1e15, which fits in i64.
pub fn max_subarray(a: &[i64]) -> i64 {
    let mut best = a[0];
    let mut cur = a[0];
    for &x in &a[1..] {
        cur = if cur > 0 { cur + x } else { x };
        if cur > best {
            best = cur;
        }
    }
    best
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    fn brute(a: &[i64]) -> i64 {
        let mut best = i64::MIN;
        for i in 0..a.len() {
            let mut s = 0;
            for &x in &a[i..] {
                s += x;
                best = best.max(s);
            }
        }
        best
    }

    #[test]
    fn basics() {
        assert_eq!(max_subarray(&[-2, 1, -3, 4, -1, 2, 1, -5, 4]), 6);
        assert_eq!(max_subarray(&[-5]), -5);
        assert_eq!(max_subarray(&[-3, -1, -2]), -1);
        assert_eq!(max_subarray(&vec![1_000_000_000; 1_000_000]), 1_000_000_000_000_000);
        assert_eq!(max_subarray(&vec![-1_000_000_000; 1_000_000]), -1_000_000_000);
    }

    proptest! {
        #[test]
        fn matches_brute(a in proptest::collection::vec(-1_000_000_000i64..=1_000_000_000, 1..60)) {
            prop_assert_eq!(max_subarray(&a), brute(&a));
        }
        #[test]
        fn matches_brute_small(a in proptest::collection::vec(-5i64..=5, 1..30)) {
            prop_assert_eq!(max_subarray(&a), brute(&a));
        }
    }
}

pub fn second_max(a: &[i64]) -> i64 {
    let max = match a.iter().copied().max() {
        Some(m) => m,
        None => return i64::MIN,
    };
    a.iter()
        .copied()
        .filter(|&x| x < max)
        .max()
        .unwrap_or(i64::MIN)
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    #[test]
    fn basics() {
        assert_eq!(second_max(&[]), i64::MIN);
        assert_eq!(second_max(&[5]), i64::MIN);
        assert_eq!(second_max(&[5, 5, 5]), i64::MIN);
        assert_eq!(second_max(&[1, 5, 5, 3]), 3);
        assert_eq!(second_max(&[i64::MAX, i64::MIN]), i64::MIN);
        assert_eq!(second_max(&[i64::MAX, i64::MAX - 1, i64::MAX]), i64::MAX - 1);
        assert_eq!(second_max(&[-3, -1, -2]), -2);
    }

    proptest! {
        #[test]
        fn matches_sort(v in proptest::collection::vec(any::<i64>(), 0..50)) {
            let mut s = v.clone();
            s.sort_unstable();
            s.dedup();
            let expected = if s.len() < 2 { i64::MIN } else { s[s.len() - 2] };
            prop_assert_eq!(second_max(&v), expected);
        }

        #[test]
        fn matches_sort_small(v in proptest::collection::vec(-3i64..3, 0..10)) {
            let mut s = v.clone();
            s.sort_unstable();
            s.dedup();
            let expected = if s.len() < 2 { i64::MIN } else { s[s.len() - 2] };
            prop_assert_eq!(second_max(&v), expected);
        }
    }
}

/// Rotate `a` to the right by `k` positions in place: the element at index i
/// moves to index (i + k) mod a.len(). An empty slice stays empty.
pub fn rotate_right(a: &mut [i64], k: usize) {
    let n = a.len();
    if n == 0 {
        return;
    }
    a.rotate_right(k % n);
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    #[test]
    fn basics() {
        let mut e: [i64; 0] = [];
        rotate_right(&mut e, 0);
        rotate_right(&mut e, usize::MAX);
        let mut a = [1, 2, 3, 4, 5];
        rotate_right(&mut a, 2);
        assert_eq!(a, [4, 5, 1, 2, 3]);
        let mut b = [1, 2, 3];
        rotate_right(&mut b, usize::MAX); // MAX % 3 == 0
        assert_eq!(b, [1, 2, 3]);
        let mut c = [1, 2];
        rotate_right(&mut c, usize::MAX); // odd -> 1
        assert_eq!(c, [2, 1]);
    }

    proptest! {
        #[test]
        fn matches_spec(v in proptest::collection::vec(any::<i64>(), 0..50), k in any::<usize>()) {
            let mut a = v.clone();
            rotate_right(&mut a, k);
            let n = v.len();
            prop_assert_eq!(a.len(), n);
            for i in 0..n {
                let j = ((i as u128 + k as u128) % n as u128) as usize;
                prop_assert_eq!(a[j], v[i]);
            }
        }
    }
}

/// Moves the distinct values of the sorted slice `a` to the front (in increasing
/// order), sets every remaining position to 0, and returns the number of
/// distinct values.
pub fn dedup_sorted(a: &mut [i64]) -> usize {
    if a.is_empty() {
        return 0;
    }
    let mut k = 1usize;
    for i in 1..a.len() {
        if a[i] != a[k - 1] {
            a[k] = a[i];
            k += 1;
        }
    }
    for x in a[k..].iter_mut() {
        *x = 0;
    }
    k
}

