/// In place, move every zero element of `a` to the end, keeping the
/// relative order of the non-zero elements.
pub fn move_zeros(a: &mut [i64]) {
    let mut w = 0;
    for r in 0..a.len() {
        if a[r] != 0 {
            a[w] = a[r];
            w += 1;
        }
    }
    for x in &mut a[w..] {
        *x = 0;
    }
}

