/// Greatest common divisor of |a| and |b| (never negative).
/// gcd(0, 0) = 0, gcd(a, 0) = |a|.
pub fn gcd(a: i64, b: i64) -> i64 {
    let mut x = a.unsigned_abs();
    let mut y = b.unsigned_abs();
    while y != 0 {
        let t = x % y;
        x = y;
        y = t;
    }
    // x <= max(|a|, |b|) <= i64::MAX within the input domain.
    x as i64
}

