/// Integer square root: the largest r >= 0 with r * r <= n.
/// For n <= 0 (n < 0 is outside the domain) returns 0.
pub fn isqrt(n: i64) -> i64 {
    if n <= 0 {
        return 0;
    }
    let n_u = n as u128;
    // Floating-point estimate, then exact correction in u128 (no overflow possible).
    let mut r = (n as f64).sqrt() as u128;
    // sqrt(i64::MAX) < 3037000500; clamp estimate to a safe range.
    if r > 3_037_000_500 {
        r = 3_037_000_500;
    }
    while r * r > n_u {
        r -= 1;
    }
    while (r + 1) * (r + 1) <= n_u {
        r += 1;
    }
    r as i64
}

