/// Sum of the half-open range `a[i..j]` (0 when `i == j`).
///
/// Within the input domain (|a[k]| <= 1e12, len <= 1e6) every partial sum is
/// bounded by 1e18 < i64::MAX, but we accumulate in i128 for extra safety.
pub fn range_sum(a: &[i64], i: usize, j: usize) -> i64 {
    if i >= j {
        return 0;
    }
    let s: i128 = a[i..j].iter().map(|&x| x as i128).sum();
    s as i64
}

