        assert_eq!(range_sum(&[1, 2, 3], 0, 3), 6);
        assert_eq!(range_sum(&[1, 2, 3], 1, 3), 5);
        assert_eq!(range_sum(&[1, -2, 3], 0, 2), -1);
    }

    #[test]
    fn extremes() {
        let m = 1_000_000_000_000i64;
        let a = vec![m; 1_000_000];
        assert_eq!(range_sum(&a, 0, a.len()), 1_000_000_000_000_000_000);
        let b = vec![-m; 1_000_000];
