/// Returns the value occurring strictly more than `a.len() / 2` times,
/// or `i64::MIN` if no such value exists.
pub fn majority(a: &[i64]) -> i64 {
    // Boyer-Moore voting.
    let mut cand = 0i64;
    let mut count = 0usize;
    for &x in a {
        if count == 0 {
            cand = x;
            count = 1;
        } else if x == cand {
            count += 1;
        } else {
            count -= 1;
        }
    }
    if count == 0 {
        return i64::MIN;
    }
    let occ = a.iter().filter(|&&x| x == cand).count();
    if occ > a.len() / 2 {
        cand
    } else {
        i64::MIN
    }
}

