pub fn longest_run(a: &[i64]) -> usize {
    if a.is_empty() {
        return 0;
    }
    let mut best = 1;
    let mut cur = 1;
    for w in a.windows(2) {
        if w[0] == w[1] {
            cur += 1;
            if cur > best {
                best = cur;
            }
        } else {
            cur = 1;
        }
    }
    best
}

