pub fn merge_sorted(a: &[i64], b: &[i64], out: &mut [i64]) {
    let (mut i, mut j, mut k) = (0usize, 0usize, 0usize);
    while i < a.len() && j < b.len() && k < out.len() {
        if b[j] < a[i] {
            out[k] = b[j];
            j += 1;
        } else {
            out[k] = a[i];
            i += 1;
        }
        k += 1;
    }
    while i < a.len() && k < out.len() {
        out[k] = a[i];
        i += 1;
        k += 1;
    }
    while j < b.len() && k < out.len() {
        out[k] = b[j];
        j += 1;
        k += 1;
    }
}

