pub fn pow_mod(base: i64, exp: i64, m: i64) -> i64 {
    let m = m as u128;
    let mut result: u128 = 1 % m;
    let mut b: u128 = (base as u128) % m;
    let mut e = exp as u64;
    while e > 0 {
        if e & 1 == 1 {
            result = result * b % m;
        }
        b = b * b % m;
        e >>= 1;
    }
    result as i64
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    fn naive(base: i64, exp: i64, m: i64) -> i64 {
        let m = m as u128;
        let b = base as u128 % m;
        let mut r = 1 % m;
        for _ in 0..exp {
            r = r * b % m;
        }
        r as i64
    }

    #[test]
    fn basics() {
        assert_eq!(pow_mod(0, 0, 1), 0);
        assert_eq!(pow_mod(0, 0, 7), 1);
        assert_eq!(pow_mod(0, 5, 7), 0);
        assert_eq!(pow_mod(2, 10, 1000), 24);
        assert_eq!(pow_mod(i64::MAX, i64::MAX, 3_000_000_000), {
            // just ensure no panic and in range
            let v = pow_mod(i64::MAX, i64::MAX, 3_000_000_000);
            assert!((0..3_000_000_000).contains(&v));
            v
        });
        // Fermat: 2^(p-1) mod p = 1 for prime p = 2_999_999_929
        assert_eq!(pow_mod(2, 2_999_999_928, 2_999_999_929), 1);
    }

    proptest! {
        #[test]
        fn matches_naive(base in 0i64..=i64::MAX, exp in 0i64..300, m in 1i64..=3_000_000_000) {
            prop_assert_eq!(pow_mod(base, exp, m), naive(base, exp, m));
        }

        #[test]
        fn exp_split(base in 0i64..=i64::MAX, a in 0i64..i64::MAX/2, b in 0i64..i64::MAX/2, m in 1i64..=3_000_000_000) {
            let lhs = pow_mod(base, a + b, m) as i128;
            let rhs = (pow_mod(base, a, m) as i128 * pow_mod(base, b, m) as i128) % m as i128;
